def levenshtein(source, target, memo=None):
    if memo is None:
        memo = {}
    if (source, target) in memo:
        return memo[(source, target)]
    if source == "" or target == "":
        result = len(source) or len(target)
    elif source[0] == target[0]:
        result = levenshtein(source[1:], target[1:], memo)
    else:
        result = 1 + min(
            levenshtein(source, target[1:], memo),
            levenshtein(source[1:], target[1:], memo),
            levenshtein(source[1:], target, memo),
        )
    memo[(source, target)] = result
    return result

def levenshtein(source, target):
    if source == "" or target == "":
        return len(source) or len(target)
    dp = [[0 for _ in range(len(target) + 1)] for _ in range(len(source) + 1)]
    for i in range(len(source) + 1):
        dp[i][0] = i
    for j in range(len(target) + 1):
        dp[0][j] = j
    for i in range(1, len(source) + 1):
        for j in range(1, len(target) + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[len(source)][len(target)]

def levenshtein(source, target):
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]
